#include "jsd/project_simulation.hpp"
namespace jsd::project {
void Simulation::reset(const Document&d){
 matrices=d.world(0,true);elapsed=0;revision=d.revision;blocked=false;bodies.clear();physics.reset();if(!enabled)return;
 WorldSettings settings;settings.gravityMps2=d.gravity;settings.workers=2;physics=std::make_unique<PhysicsWorld>(settings);
 for(auto&o:d.objects){if(!o.visible||(o.kind!=Kind::Mesh&&o.kind!=Kind::Collider)||o.physics.mode==0||geometry(o).faces.empty())continue;auto mesh=evaluated(o);auto[lo,hi]=bounds(mesh);V3 center=(lo+hi)*.5f;auto t=decompose(matrices.at(o.id));V3 half{(hi.x-lo.x)*std::abs(t.scale.x)*.5f,(hi.y-lo.y)*std::abs(t.scale.y)*.5f,(hi.z-lo.z)*std::abs(t.scale.z)*.5f};half={std::max(half.x,.005f),std::max(half.y,.005f),std::max(half.z,.005f)};
  auto&p=o.physics;BodySettings s;s.position=rf::transformPoint(matrices.at(o.id),center);s.rotation=orientation(t);s.halfExtent=half;s.motion=p.mode==1?MotionType::Static:p.mode==2?MotionType::Kinematic:MotionType::Dynamic;s.mass=p.mass;s.massMode=p.densityMode?MassMode::Density:MassMode::ExplicitKilograms;s.densityKgPerM3=p.density;s.friction=p.friction;s.restitution=p.restitution;s.linearDampingPerSecond=p.damping;s.angularDampingPerSecond=p.angularDamping;s.continuous=p.continuous;
  Body b;if(p.shape==1)b=physics->sphere(s,std::max({half.x,half.y,half.z}));else if(p.shape==2)b=physics->capsule(s,std::max(.005f,half.y-std::max(half.x,half.z)),std::max(half.x,half.z));else if(p.shape==3)b=physics->cylinder(s,half.y,std::max(half.x,half.z));else b=physics->box(s);
  if(p.mode==3){physics->velocity(b,p.velocity);physics->angularVelocity(b,p.angularVelocity);}bodies[o.id]={b,center,t.scale,p.mode};
 }
}
void Simulation::tick(const Document&d,float dt){elapsed+=dt;matrices=d.world(elapsed,true);if(!physics)return;for(auto &[id,b]:bodies)if(b.mode==2){auto t=decompose(matrices.at(id));auto result=physics->moveKinematic(b.body,rf::transformPoint(matrices.at(id),b.center),orientation(t),dt);blocked|=result.blocked;}
 physics->step(dt);for(auto &[id,b]:bodies){auto state=physics->state(b.body);V3 scaled{b.center.x*b.scale.x,b.center.y*b.scale.y,b.center.z*b.scale.z};auto r=rf::compose({},state.rotation);matrices[id]=rf::compose(state.position-rf::transformVector(r,scaled),state.rotation,b.scale);}
 // Nonphysical descendants follow a physically moved parent rather than the authored parent.
 std::function<Mat4(Id)> resolve=[&](Id id){auto*o=d.find(id);if(!o||bodies.contains(id)||!o->parent)return matrices.at(id);matrices[id]=resolve(o->parent)*matrix(evaluate(*o,elapsed));return matrices[id];};for(auto&o:d.objects)resolve(o.id);(void)physics->contacts();
}
void Simulation::seek(const Document&d,float seconds){if(!std::isfinite(seconds)||seconds<0||seconds>600)throw std::runtime_error("Invalid preview time");if(!enabled){elapsed=seconds;revision=d.revision;matrices=d.world(seconds,true);return;}reset(d);unsigned steps=unsigned(std::floor(double(seconds)*120));for(unsigned i=0;i<steps;i++)tick(d,1.f/120);float remainder=seconds-elapsed;if(remainder>1e-6f)tick(d,std::min(remainder,1.f/120));elapsed=seconds;}
void Simulation::advance(const Document&d,float dt){if(revision!=d.revision)seek(d,elapsed);if(!enabled){elapsed+=dt;matrices=d.world(elapsed,true);return;}if(!physics)reset(d);while(dt>1e-7f){float step=std::min(dt,1.f/120);tick(d,step);dt-=step;}}
void Simulation::bake(Document&d,std::span<const Id> ids,float duration,float fps){if(duration<=0||duration>60||fps<1||fps>120)throw std::runtime_error("Bake supports 0-60 s and 1-120 fps");Document source=d;enabled=true;reset(source);std::map<Id,std::vector<Key>>keys;for(unsigned i=0;i<=unsigned(std::ceil(duration*fps));i++){float t=std::min(duration,i/fps);if(i)advance(source,t-elapsed);for(Id id:ids){auto*o=d.find(id);if(!o||!bodies.contains(id))continue;auto local=o->parent?rf::inverse(matrices.at(o->parent))*matrices.at(id):matrices.at(id);keys[id].push_back({t,decompose(local),1});}}for(auto &[id,k]:keys){auto*o=d.find(id);o->motion.keys=std::move(k);o->motion.sharedKeys.reset();o->motion.clipFile.clear();o->motion.relative=false;o->motion.behavior=Behavior::None;o->physics.mode=2;}++d.revision;reset(d);}
}
